#[test]
fn get_order_get_order_400_decodes_declared_error() {
    let Some(config) = configured_client() else {
        return;
    };
    let config = ClientConfig {
        base_url: config
            .base_url
            .map(|base_url| format!("{base_url}/__mockStatus/400")),
        ..config
    };
    let result = domains_registrar::get_order(
        &config,
        domains_registrar::GetOrderParams {
            order_id: decode(fixture(r#""order-1""#)),
            team_id: Some(decode(fixture(r#""team_1a2b3c4d5e6f7g8h9i0j1k2l""#))),
        },
        None,
    );
    let Err(::octridev_vercel::errors::SdkError::Http(error)) = result else {
        panic!("get_order did not fail with SdkError::Http on 400");
    };
    assert_eq!(error.status_code, 400);
    let actual = serde_json::to_value(&error.data).expect("serialize declared error body");
    let expected = fixture(
        r#"{"issues":[{"path":["path"],"message":"example text"}],"message":"example text"}"#,
    );
    assert!(
        representative(&actual, &expected),
        "get_order decoded error body {actual}, expected representative {expected}"
    );
}

