#[test]
fn upsert_connector_project_connection_upsert_connector_project_connection_400_decodes_declared_error(
) {
    let Some(config) = configured_client() else {
        return;
    };
    let config = ClientConfig {
        base_url: config
            .base_url
            .map(|base_url| format!("{base_url}/__mockStatus/400")),
        ..config
    };
    let result = connect::upsert_connector_project_connection(
        &config,
        connect::UpsertConnectorProjectConnectionParams {
            connector: decode(fixture(r#""connector""#)),
            project_id: decode(fixture(r#""project-1""#)),
            environments: decode(fixture(r#"["env_"]"#)),
            team_id: Some(decode(fixture(r#""team_1a2b3c4d5e6f7g8h9i0j1k2l""#))),
            slug: Some(decode(fixture(r#""my-team-url-slug""#))),
        },
        None,
    );
    let Err(::octridev_vercel::errors::SdkError::Http(error)) = result else {
        panic!("upsert_connector_project_connection did not fail with SdkError::Http on 400");
    };
    assert_eq!(error.status_code, 400);
    let actual = serde_json::to_value(&error.data).expect("serialize declared error body");
    let expected = fixture(r#"{"error":{"code":"code","message":"example text"}}"#);
    assert!(
        representative(&actual, &expected),
        "upsert_connector_project_connection decoded error body {actual}, expected representative {expected}"
    );
}

